{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MapleMonk.zouk_express_delivery_report AS WITH CP_Latest AS ( SELECT CAST(order_id AS STRING) AS order_id, awb_number, courier_partner, current_status, SAFE_CAST(delivery_date AS DATETIME) AS delivery_date, SAFE_CAST(pickup_date AS DATETIME) AS pickup_date, SAFE_CAST(orderplaced_date AS DATETIME) AS orderplaced_date, Payment_method, min_sla, max_sla, ROW_NUMBER() OVER ( PARTITION BY order_id ORDER BY COALESCE( SAFE_CAST(delivery_date AS DATETIME), SAFE_CAST(pickup_date AS DATETIME), SAFE_CAST(orderplaced_date AS DATETIME) ) DESC ) AS rn FROM `MapleMonk.zouk_CLICKPOST_FACT_ITEMS` ), CP AS ( SELECT * EXCEPT(rn) FROM CP_Latest WHERE rn = 1 ), Orders AS ( SELECT LTRIM(Display_Order_Code, \'#\') AS order_id, Sale_Order_Item_Code, CAST(Order_Date_as_dd_mm_yyyy_hh_MM_ss AS DATETIME) AS Order_Timestamp, DATE(CAST(Order_Date_as_dd_mm_yyyy_hh_MM_ss AS DATETIME)) AS Order_Date, TIME(CAST(Order_Date_as_dd_mm_yyyy_hh_MM_ss AS DATETIME)) AS Order_Time, CASE WHEN LOWER(IFNULL(tagsfetched, \'\')) LIKE \'%express%\' THEN \'Express\' ELSE \'Standard\' END AS Is_Express, CASE WHEN TIME(CAST(Order_Date_as_dd_mm_yyyy_hh_MM_ss AS DATETIME)) < TIME(13, 0, 0) THEN DATE(CAST(Order_Date_as_dd_mm_yyyy_hh_MM_ss AS DATETIME)) ELSE DATE_ADD( DATE(CAST(Order_Date_as_dd_mm_yyyy_hh_MM_ss AS DATETIME)), INTERVAL 1 DAY ) END AS Expected_Dispatch_Date, Sale_Order_Item_Status, CAST(Shipping_Address_Pincode AS STRING) AS Pincode, Tracking_Number, Shipping_Courier, DATE(SAFE_CAST(Dispatch_Date AS DATETIME)) AS UC_Dispatch_Date, Channel_Name, Item_SKU_Code, Item_Type_Name, Selling_Price, Facility FROM `MapleMonk.zouk_db_updated_get_sale_orders` WHERE LOWER(Channel_Name) LIKE \'%shopify\' and lower(Sale_Order_Item_Status) not like \'%cancel%\' ), Zones AS ( SELECT CAST(Pincode AS STRING) AS Pincode, Zone FROM `MapleMonk.Zouk_MM_Zone_Mapping` ) SELECT o.order_id, o.Sale_Order_Item_Code, o.Order_Timestamp, o.Order_Date, o.Order_Time, o.Is_Express, o.Channel_Name, o.Facility, o.Item_SKU_Code, o.Item_Type_Name, o.Selling_Price, o.Pincode, COALESCE(z.Zone, \'Unknown\') AS Zone, COALESCE(cp.courier_partner, o.Shipping_Courier) AS Courier, COALESCE(cp.awb_number, o.Tracking_Number) AS AWB_Number, o.Expected_Dispatch_Date, o.UC_Dispatch_Date AS Actual_Dispatch_Date, DATE(cp.delivery_date) AS Delivery_Date, DATE_DIFF(o.UC_Dispatch_Date, o.Expected_Dispatch_Date, DAY ) AS Dispatch_Delay_Days, DATE_DIFF( DATE(cp.delivery_date), o.Order_Date, DAY ) AS Delivery_Days, COALESCE(cp.current_status, o.Sale_Order_Item_Status) AS Shipment_Status, CASE WHEN UPPER(COALESCE(cp.current_status, o.Sale_Order_Item_Status)) LIKE \'%DELIVERED%\' AND UPPER(COALESCE(cp.current_status, o.Sale_Order_Item_Status)) NOT LIKE \'%RTO%\' THEN \'Delivered\' WHEN UPPER(COALESCE(cp.current_status, o.Sale_Order_Item_Status)) LIKE \'%RTO%\' OR UPPER(COALESCE(cp.current_status, o.Sale_Order_Item_Status)) LIKE \'%RETURN%\' THEN \'RTO\' WHEN UPPER(COALESCE(cp.current_status, o.Sale_Order_Item_Status)) LIKE \'%TRANSIT%\' OR UPPER(COALESCE(cp.current_status, o.Sale_Order_Item_Status)) LIKE \'%INTRANSIT%\' OR UPPER(COALESCE(cp.current_status, o.Sale_Order_Item_Status)) LIKE \'%PICKED%\' THEN \'In Transit\' WHEN UPPER(COALESCE(cp.current_status, o.Sale_Order_Item_Status)) LIKE \'%FAKE%\' OR UPPER(COALESCE(cp.current_status, o.Sale_Order_Item_Status)) LIKE \'%UNDELIVERED%\' OR UPPER(COALESCE(cp.current_status, o.Sale_Order_Item_Status)) LIKE \'%FAILED%\' OR UPPER(COALESCE(cp.current_status, o.Sale_Order_Item_Status)) LIKE \'%NDR%\' THEN \'Failed Delivery\' ELSE \'Other\' END AS Status_Group, CASE WHEN COALESCE(z.Zone, \'Unknown\') = \'Zone A\' THEN 2 WHEN COALESCE(z.Zone, \'Unknown\') = \'Zone B\' THEN 3 WHEN COALESCE(z.Zone, \'Unknown\') = \'Zone C\' THEN 4 ELSE NULL END AS SLA_Threshold_Days, CASE WHEN DATE(cp.delivery_date) IS NULL THEN NULL WHEN COALESCE(z.Zone, \'Unknown\') = \'Zone A\' AND DATE_DIFF(DATE(cp.delivery_date), o.UC_Dispatch_Date, DAY) <= 2 THEN TRUE WHEN COALESCE(z.Zone, \'Unknown\') = \'Zone B\' AND DATE_DIFF(DATE(cp.delivery_date), o.UC_Dispatch_Date, DAY) <= 3 THEN TRUE WHEN COALESCE(z.Zone, \'Unknown\') = \'Zone C\' AND DATE_DIFF(DATE(cp.delivery_date), o.UC_Dispatch_Date, DAY) <= 4 THEN TRUE ELSE FALSE END AS Within_Delivery_SLA, CASE WHEN COALESCE(DATE(cp.pickup_date), o.UC_Dispatch_Date) IS NULL THEN \'Not Dispatched\' WHEN DATE_DIFF(o.UC_Dispatch_Date, o.Expected_Dispatch_Date, DAY) = 0 THEN \'Same Day\' WHEN DATE_DIFF(o.UC_Dispatch_Date, o.Expected_Dispatch_Date, DAY) = 1 THEN \'Next Day\' WHEN DATE_DIFF(o.UC_Dispatch_Date, o.Expected_Dispatch_Date, DAY) = 2 THEN \'3 Days\' WHEN DATE_DIFF( o.UC_Dispatch_Date, o.Expected_Dispatch_Date, DAY) = 3 THEN \'4 Days\' ELSE \'5+ Days\' END AS Dispatch_Bucket, CASE WHEN DATE(cp.delivery_date) IS NULL THEN \'Not Delivered\' WHEN DATE_DIFF(DATE(cp.delivery_date), o.Order_Date, DAY) <= 1 THEN \'Same Day\' WHEN DATE_DIFF(DATE(cp.delivery_date), o.Order_Date, DAY) = 2 THEN \'Next Day\' WHEN DATE_DIFF(DATE(cp.delivery_date), o.Order_Date, DAY) = 3 THEN \'3 Days\' WHEN DATE_DIFF(DATE(cp.delivery_date), o.Order_Date, DAY) = 4 THEN \'4 Days\' ELSE \'5+ Days\' END AS Delivery_Bucket FROM Orders o LEFT JOIN CP cp ON o.order_id = cp.order_id LEFT JOIN Zones z ON o.Pincode = z.Pincode;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            